package ly.dojoon.poslink

import ly.dojoon.poslink.protocol.FrameCodec
import ly.dojoon.poslink.protocol.Role
import ly.dojoon.poslink.security.Crypto
import ly.dojoon.poslink.security.P256KeyPair
import ly.dojoon.poslink.security.PairingCrypto
import ly.dojoon.poslink.security.hexToBytes
import ly.dojoon.poslink.security.toHex
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/** The shared conformance vectors in spec/vectors (generated by the Python reference). */
class VectorsTest {

    private fun vectors(name: String): JSONObject {
        var dir: File? = File("").absoluteFile
        while (dir != null && !File(dir, "spec/vectors/$name").exists()) dir = dir.parentFile
        return JSONObject(File(dir ?: error("spec/vectors not found"), "spec/vectors/$name").readText())
    }

    private fun hex(o: JSONObject, key: String) = o.getString(key).hexToBytes()

    @Test fun hkdfMatchesRfc5869() {
        val v = vectors("crypto.json").getJSONObject("hkdf_rfc5869_a1")
        val okm = Crypto.hkdf(hex(v, "ikm"), hex(v, "salt"), hex(v, "info"), v.getInt("length"))
        assertEquals(v.getString("okm"), okm.toHex())
    }

    @Test fun pairingAndSessionKeys() {
        val v = vectors("crypto.json")
        val p = v.getJSONObject("pairing")
        val c = p.getJSONObject("cashier")
        val t = p.getJSONObject("terminal")
        val kc = P256KeyPair.fromPrivateScalar(hex(c, "privateScalar"))
        val kt = P256KeyPair.fromPrivateScalar(hex(t, "privateScalar"))
        assertEquals(c.getString("publicKey"), kc.publicKey.toHex())
        assertEquals(t.getString("publicKey"), kt.publicKey.toHex())

        assertEquals(p.getString("commit"), PairingCrypto.commit(kc.publicKey, hex(c, "nonce")).toHex())
        val shared = kc.sharedSecret(kt.publicKey)
        assertEquals(p.getString("sharedSecret"), shared.toHex())
        assertEquals(p.getString("sharedSecret"), kt.sharedSecret(kc.publicKey).toHex())

        val th = PairingCrypto.transcriptHash(
            hex(c, "deviceId"), hex(t, "deviceId"), kc.publicKey, kt.publicKey, hex(c, "nonce"), hex(t, "nonce"),
        )
        assertEquals(p.getString("transcriptHash"), th.toHex())
        val key = PairingCrypto.pairingKey(shared, th)
        assertEquals(p.getString("pairingKey"), key.toHex())
        assertEquals(p.getString("code"), PairingCrypto.code(shared, th))
        assertEquals(p.getString("confirmMacCashier"), PairingCrypto.confirmMac(key, Role.CASHIER.byte, th).toHex())
        assertEquals(p.getString("confirmMacTerminal"), PairingCrypto.confirmMac(key, Role.TERMINAL.byte, th).toHex())

        val frames = p.getJSONArray("frames")
        for (i in 0 until frames.length()) {
            val f = frames.getJSONObject(i)
            val encoded = FrameCodec.encode(f.getInt("type"), f.getInt("seq"), f.getString("payload").toByteArray())
            assertEquals(f.getString("name"), f.getString("hex"), encoded.toHex())
        }

        val s = v.getJSONObject("session")
        val sk = PairingCrypto.sessionKey(
            hex(s, "pairingKey"), hex(s, "cashierLinkNonce"), hex(s, "terminalLinkNonce"),
            hex(s, "cashierDeviceId"), hex(s, "terminalDeviceId"),
        )
        assertEquals(s.getString("sessionKey"), sk.toHex())
    }

    @Test fun invalidPublicKeyIsRejected() {
        val bad = ByteArray(65).also { it[0] = 4; it[1] = 1 }
        val ok = runCatching { P256KeyPair.generate().sharedSecret(bad) }.isSuccess
        assertFalse("a point off the curve must be refused", ok)
    }

    @Test fun framesEncodeExactly() {
        val v = vectors("frames.json")
        val sk = hex(v, "sessionKey")
        val cases = v.getJSONArray("frames")
        for (i in 0 until cases.length()) {
            val f = cases.getJSONObject(i)
            val payload = f.getString("payload").toByteArray()
            val bytes = if (f.getBoolean("authenticated")) {
                val role = if (f.getString("senderRole") == "C") Role.CASHIER else Role.TERMINAL
                FrameCodec.encode(f.getInt("type"), f.getInt("seq"), payload, f.getLong("counter"), sk, role)
            } else {
                FrameCodec.encode(f.getInt("type"), f.getInt("seq"), payload)
            }
            assertEquals(f.getString("name"), f.getString("hex"), bytes.toHex())
        }
    }

    @Test fun streamDecoding() {
        val v = vectors("frames.json")
        val d = v.getJSONObject("decoding")
        val decoder = FrameCodec.Decoder()
        val frames = buildList {
            val chunks = d.getJSONArray("chunks")
            for (i in 0 until chunks.length()) addAll(decoder.add(chunks.getString(i).hexToBytes()))
        }
        val expected = d.getJSONArray("expected")
        assertEquals(expected.length(), frames.size)
        for (i in 0 until expected.length()) {
            val e = expected.getJSONObject(i)
            assertEquals(e.getInt("version"), frames[i].version)
            assertEquals(e.getInt("type"), frames[i].type)
            assertEquals(e.getInt("seq"), frames[i].seq)
            assertEquals(e.getLong("counter"), frames[i].counter)
        }
        assertEquals(d.getInt("crcErrors"), decoder.crcErrors)

        val sk = hex(v, "sessionKey")
        assertTrue("mac of the cashier's SALE_REQUEST", frames[0].verify(sk, Role.CASHIER))
        assertFalse("same frame as if sent by the terminal", frames[0].verify(sk, Role.TERMINAL))
        assertTrue(frames[2].isUnauthenticated)
    }
}
